package com.example.starter.water;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 供水窗口实体。创建后不可修改；时间字段为 UTC 时刻，水量单位立方米（最多 3 位小数）。
 */
public record WaterWindow(
        long id,
        String windowKey,
        String channelId,
        Instant startUtc,
        Instant endUtc,
        BigDecimal plannedVolume,
        Instant createdAt) {
}

package com.example.starter.water;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 配水申请实体。状态机：REQUESTED -> APPROVED，任意非取消态可被申请人取消为 CANCELLED，取消不可恢复。
 */
public record WaterAllocation(
        long id,
        String allocationKey,
        long windowId,
        String userId,
        BigDecimal volume,
        String applicant,
        String status,
        Instant createdAt,
        Instant updatedAt) {

    /** 已申请，待批准。 */
    public static final String STATUS_REQUESTED = "REQUESTED";
    /** 已批准，占用水量。 */
    public static final String STATUS_APPROVED = "APPROVED";
    /** 已取消，立即释放占用水量，不可恢复。 */
    public static final String STATUS_CANCELLED = "CANCELLED";
}

package com.example.starter.water;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 限供记录实体。同一窗口至多一条 ACTIVE 记录；取消后保留历史，窗口恢复计划水量。
 */
public record WaterRestriction(
        long id,
        long windowId,
        BigDecimal limitVolume,
        String status,
        Instant createdAt,
        Instant cancelledAt) {

    /** 生效中。 */
    public static final String STATUS_ACTIVE = "ACTIVE";
    /** 已取消。 */
    public static final String STATUS_CANCELLED = "CANCELLED";
}

