package com.example.starter.water;

import java.time.Instant;

/**
 * 幂等命令日志实体：记录某 commandKey 首次成功执行的操作、参数指纹与响应快照。
 */
public record CommandRecord(
        String commandKey,
        String operation,
        String paramsHash,
        int httpStatus,
        String responseBody,
        Instant createdAt) {
}

package com.example.starter.water;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带可区分的 HTTP 状态与错误码。
 * 400 参数非法、404 资源不存在、409 操作人/状态/幂等冲突、422 配额不足。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    /** 400：请求参数非法。 */
    public static ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
    }

    /** 404：资源不存在。 */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    /** 409：操作人、状态或幂等键冲突。 */
    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    /** 422：配额不足（批准超限或限供低于已批准总量）。 */
    public static ApiException quotaExceeded(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "QUOTA_EXCEEDED", message);
    }
}

package com.example.starter.water;

/**
 * 统一错误响应体。
 *
 * @param code    可区分的错误码，如 INVALID_ARGUMENT / NOT_FOUND / STATE_CONFLICT / ACTOR_MISMATCH / QUOTA_EXCEEDED
 * @param message 错误描述
 */
public record ErrorResponse(String code, String message) {
}

